# Exercises written from the notes, one set per chapter (enterprise database).
EX = []
def X(s, q, sol, hint=''):
    EX.append(dict(s=s, q=q, sol=sol.strip(), hint=hint, db='enterprise'))

# ---------- select (chapter 2)
S='select'
X(S,"Show every column of the departments table.","SELECT * FROM departments;","SELECT * FROM …")
X(S,"Show the project name and location of every project.","SELECT project_name, location FROM projects;")
X(S,"Show each employee's last name and salary, with the headers <b>Name</b> and <b>Yearly pay</b> (keep the capitals and the space).","SELECT last_name AS \"Name\", salary AS \"Yearly pay\" FROM employees;","Double quotes keep capitals and spaces.")
X(S,"Show each employee's first name and last name glued together in one column called <b>full_name</b>, e.g. <i>Bijoy Bordoloi</i>.","SELECT first_name || ' ' || last_name AS full_name FROM employees;")
X(S,"Show each employee's last name and their salary per month (salary divided by 12).","SELECT last_name, salary / 12 FROM employees;")
X(S,"Calculate 2 + 2 and today's date in one query, without a table.","SELECT 2 + 2, CURRENT_DATE;","SELECT without FROM.")
X(S,"Show the different genders that occur in employees, each once.","SELECT DISTINCT gender FROM employees;")
X(S,"Show the different combinations of department and gender in employees.","SELECT DISTINCT department_id, gender FROM employees;")
X(S,"Show last name and department of the employees in department 3.","SELECT last_name, department_id FROM employees WHERE department_id = 3;")
X(S,"Show the employees (last name, birth date) born before 1 January 1980.","SELECT last_name, birth_date FROM employees WHERE birth_date < '01-01-1980';","Dates go in single quotes.")
X(S,"Show last name and salary of the employees earning between 30000 and 45000, both limits included.","SELECT last_name, salary FROM employees WHERE salary BETWEEN 30000 AND 45000;")
X(S,"Find the employee whose first name is douglas, however it's capitalised in the table.","SELECT * FROM employees WHERE LOWER(first_name) = 'douglas';","Convert the column with LOWER or UPPER first.")
X(S,"Show the last names that contain an 'e' anywhere (upper or lower case).","SELECT last_name FROM employees WHERE LOWER(last_name) LIKE '%e%';")
X(S,"Show the last names whose third letter is an 'r'.","SELECT last_name FROM employees WHERE LOWER(last_name) LIKE '__r%';","Two underscores, then r.")
X(S,"Show last name, salary and department of employees in department 7 who earn more than 30000.","SELECT last_name, salary, department_id FROM employees WHERE department_id = 7 AND salary > 30000;")
X(S,"Show last name, gender and department of the women who work in department 3 or 7.","SELECT last_name, gender, department_id FROM employees WHERE gender = 'F' AND (department_id = 3 OR department_id = 7);","Brackets around the OR.")
X(S,"Show the projects located in Eindhoven or Maarssen, using IN.","SELECT * FROM projects WHERE location IN ('Eindhoven', 'Maarssen');")
X(S,"Show the employees who do NOT live in the province NB or LI.","SELECT last_name, province FROM employees WHERE province NOT IN ('NB', 'LI');")
X(S,"Show the employees that have an infix (the infix is filled in).","SELECT first_name, infix, last_name FROM employees WHERE infix IS NOT NULL;")
X(S,"Show the tasks with hours filled in, sorted from most to fewest hours.","SELECT * FROM tasks WHERE hours IS NOT NULL ORDER BY hours DESC;")
X(S,"Show all employees sorted by department (ascending) and within each department by salary from high to low. Show department, last name and salary.","SELECT department_id, last_name, salary FROM employees ORDER BY department_id, salary DESC;")
X(S,"Show all tasks sorted by hours from high to low, but with the empty hours at the bottom.","SELECT * FROM tasks ORDER BY hours DESC NULLS LAST;")
X(S,"Show the 3 youngest employees (last name, birth date), youngest first.","SELECT last_name, birth_date FROM employees ORDER BY birth_date DESC FETCH FIRST 3 ROWS ONLY;","Youngest = latest birth date.")
X(S,"Sorted by last name, skip the first 2 employees and show the next 3 (last name only).","SELECT last_name FROM employees ORDER BY last_name OFFSET 2 ROWS FETCH NEXT 3 ROWS ONLY;")
X(S,"Show the employees with the 2 highest salaries, including everyone who shares the second-highest salary. Sort from high to low.","SELECT last_name, salary FROM employees ORDER BY salary DESC FETCH FIRST 2 ROWS WITH TIES;")

# ---------- functions (chapter 3)
S='functions'
X(S,"Show every birth date of the employees written as day/month/year, e.g. <i>10/11/1977</i>.","SELECT last_name, TO_CHAR(birth_date, 'DD/MM/YYYY') FROM employees;")
X(S,"Show each family member's name and the month they were born in as a word, without extra spaces (e.g. <i>May</i>).","SELECT name, TO_CHAR(birth_date, 'FMMonth') FROM family_members;","FM removes the padding.")
X(S,"Show each employee's last name and the year they were born as a number.","SELECT last_name, date_part('year', birth_date) FROM employees;")
X(S,"Show each employee's last name and their age in whole years.","SELECT last_name, date_part('year', age(birth_date)) FROM employees;")
X(S,"Show the employees who are older than 45. Show last name and birth date.","SELECT last_name, birth_date FROM employees WHERE age(birth_date) > interval '45 years';")
X(S,"Show each department name and the date exactly 10 years after its manager started (mgr_start_date + 10 years).","SELECT department_name, mgr_start_date + interval '10 years' FROM departments;")
X(S,"Show each family member's name and how many days old they are.","SELECT name, current_date - birth_date FROM family_members;")
X(S,"Show the employees born on a Sunday (use date_part with 'dow').","SELECT last_name, birth_date FROM employees WHERE date_part('dow', birth_date) = 0;","dow: Sunday is 0.")
X(S,"Show each employee's last name in capitals and the number of letters in it.","SELECT UPPER(last_name), LENGTH(last_name) FROM employees;")
X(S,"Show the first letter of the first name followed by a dot and the last name, e.g. <i>B. Bordoloi</i>.","SELECT SUBSTRING(first_name, 1, 1) || '. ' || last_name FROM employees;")
X(S,"Show each last name and the position of the first 'e' in it (0 when there is none).","SELECT last_name, POSITION('e' IN last_name) FROM employees;")
X(S,"Show the full name of every employee (first name, infix, last name) separated by spaces, without the result becoming empty when infix is NULL.","SELECT CONCAT_WS(' ', first_name, infix, last_name) FROM employees;","CONCAT_WS skips NULLs.")
X(S,"Show each project name padded on the left with dots to 25 characters.","SELECT LPAD(project_name, 25, '.') FROM projects;")
X(S,"Show each street with 'straat' replaced by 'str.'","SELECT REPLACE(street, 'straat', 'str.') FROM employees;")
X(S,"Show each salary divided by 12, rounded to 1 decimal and, in another column, truncated to whole euros.","SELECT ROUND(salary / 12, 1), TRUNC(salary / 12) FROM employees;")
X(S,"Show the salary of every employee formatted with 2 decimals and no leading spaces, e.g. <i>55000.00</i>.","SELECT TO_CHAR(salary, 'FM99999.00') FROM employees;")
X(S,"Show the employees whose employee_id, converted to a number, is bigger than 999500000.","SELECT employee_id, last_name FROM employees WHERE CAST(employee_id AS INT) > 999500000;","employee_id is text: CAST it.")
X(S,"Show the remainder of each parking spot number divided by 2 (MOD), next to the last name.","SELECT last_name, MOD(parking_spot, 2) FROM employees;")

# ---------- joins (chapter 4)
S='joins'
X(S,"Show each employee's last name with the name of the department they work in.","SELECT e.last_name, d.department_name FROM employees e JOIN departments d ON (e.department_id = d.department_id);")
X(S,"Same, but only for the department Production, sorted by last name.","SELECT e.last_name, d.department_name FROM employees e JOIN departments d ON (e.department_id = d.department_id) WHERE d.department_name = 'Production' ORDER BY e.last_name;")
X(S,"Show each employee's last name and department name, joining with USING.","SELECT last_name, department_name FROM employees JOIN departments USING (department_id);","With USING, write department_id without prefix.")
X(S,"Show each department name with the last name of the employee who manages it.","SELECT d.department_name, e.last_name FROM departments d JOIN employees e ON (d.manager_id = e.employee_id);","departments.manager_id points to employees.employee_id.")
X(S,"Show each department name with all its locations.","SELECT d.department_name, l.location FROM departments d JOIN locations l ON (d.department_id = l.department_id);")
X(S,"Show for every task: employee last name, project name and hours.","SELECT e.last_name, p.project_name, t.hours FROM employees e JOIN tasks t ON (e.employee_id = t.employee_id) JOIN projects p ON (t.project_id = p.project_id);")
X(S,"Show the last names of employees who work on the project Warehouse.","SELECT e.last_name FROM employees e JOIN tasks t ON (e.employee_id = t.employee_id) JOIN projects p ON (t.project_id = p.project_id) WHERE p.project_name = 'Warehouse';")
X(S,"Show each family member's name, relationship and the department name of their employee.","SELECT f.name, f.relationship, d.department_name FROM family_members f JOIN employees e ON (f.employee_id = e.employee_id) JOIN departments d ON (e.department_id = d.department_id);")
X(S,"Show each employee's last name with the last name of their boss, in a column called <b>boss</b>.","SELECT e.last_name, b.last_name AS boss FROM employees e JOIN employees b ON (e.manager_id = b.employee_id);","Self join: e = employee, b = boss.")
X(S,"Who works in the same department as Joyner (Joyner herself not included)?","SELECT e.last_name FROM employees j JOIN employees e ON (j.department_id = e.department_id) WHERE j.last_name = 'Joyner' AND e.last_name <> 'Joyner';")
X(S,"Who earns less than Joosten? Show last name and salary.","SELECT e.last_name, e.salary FROM employees e JOIN employees j ON (e.salary < j.salary) WHERE j.last_name = 'Joosten';")
X(S,"Show pairs of employees in the same department, each pair only once (department, name 1, name 2).","SELECT e1.department_id, e1.last_name, e2.last_name FROM employees e1 JOIN employees e2 ON (e1.department_id = e2.department_id AND e1.employee_id < e2.employee_id);","Use < instead of <>.")
X(S,"Show the employees whose boss's boss is Bordoloi.","SELECT e.last_name FROM employees e JOIN employees b ON (e.manager_id = b.employee_id) JOIN employees bb ON (b.manager_id = bb.employee_id) WHERE bb.last_name = 'Bordoloi';")
X(S,"Show each project name with the name of the department that supports it and the employees (last names) working on it.","SELECT p.project_name, d.department_name, e.last_name FROM projects p JOIN departments d ON (p.department_id = d.department_id) JOIN tasks t ON (p.project_id = t.project_id) JOIN employees e ON (t.employee_id = e.employee_id);")

# ---------- group (chapter 5)
S='group'
X(S,"How many employees are there, and what is the total of all salaries?","SELECT COUNT(*), SUM(salary) FROM employees;")
X(S,"Show the lowest, highest and average salary (average rounded to whole euros).","SELECT MIN(salary), MAX(salary), ROUND(AVG(salary)) FROM employees;")
X(S,"How many tasks are there, and for how many are the hours filled in?","SELECT COUNT(*), COUNT(hours) FROM tasks;","COUNT(column) skips NULL.")
X(S,"How many different employees have at least one task?","SELECT COUNT(DISTINCT employee_id) FROM tasks;")
X(S,"What is the birth date of the oldest family member?","SELECT MIN(birth_date) FROM family_members;")
X(S,"Show for each department the number of employees.","SELECT department_id, COUNT(*) FROM employees GROUP BY department_id;")
X(S,"Show for each gender the average salary, rounded.","SELECT gender, ROUND(AVG(salary)) FROM employees GROUP BY gender;")
X(S,"Show for each employee_id the total hours they worked (tasks).","SELECT employee_id, SUM(hours) FROM tasks GROUP BY employee_id;")
X(S,"Show for each relationship type (PARTNER, SON, DAUGHTER) how many family members there are.","SELECT relationship, COUNT(*) FROM family_members GROUP BY relationship;")
X(S,"Show for each department and gender combination the number of employees.","SELECT department_id, gender, COUNT(*) FROM employees GROUP BY department_id, gender;")
X(S,"Show the departments whose total salary cost is more than 100000.","SELECT department_id, SUM(salary) FROM employees GROUP BY department_id HAVING SUM(salary) > 100000;")
X(S,"Show the employee_ids that work on more than 2 projects.","SELECT employee_id, COUNT(*) FROM tasks GROUP BY employee_id HAVING COUNT(*) > 2;")
X(S,"Show for each department the average salary of the men only, but only departments where that average is above 35000.","SELECT department_id, AVG(salary) FROM employees WHERE gender = 'M' GROUP BY department_id HAVING AVG(salary) > 35000;","Men → WHERE. Average → HAVING.")
X(S,"Show each department name with its number of employees, sorted from most to fewest.","SELECT d.department_name, COUNT(*) FROM employees e JOIN departments d ON (e.department_id = d.department_id) GROUP BY d.department_name ORDER BY 2 DESC;")
X(S,"Show each project name with the total hours worked on it, only projects with more than 40 hours.","SELECT p.project_name, SUM(t.hours) FROM projects p JOIN tasks t ON (p.project_id = t.project_id) GROUP BY p.project_name HAVING SUM(t.hours) > 40;")
X(S,"What is the average of the lowest salaries of all departments? (subquery in FROM)","SELECT ROUND(AVG(min_sal)) FROM (SELECT MIN(salary) AS min_sal FROM employees GROUP BY department_id) x;")

# ---------- outer (chapter 6)
S='outer'
X(S,"Show every employee's last name with the names of their family members, also employees without family.","SELECT e.last_name, f.name FROM employees e LEFT JOIN family_members f ON (e.employee_id = f.employee_id);")
X(S,"Show the last names of the employees who have no family members.","SELECT e.last_name FROM employees e LEFT JOIN family_members f ON (e.employee_id = f.employee_id) WHERE f.employee_id IS NULL;","Test a column that is never empty in a real family row.")
X(S,"Show every employee with the last name of their boss, the employee without boss included.","SELECT e.last_name, b.last_name AS boss FROM employees e LEFT JOIN employees b ON (e.manager_id = b.employee_id);")
X(S,"Show the last names of employees who manage nobody.","SELECT e.last_name FROM employees e LEFT JOIN employees s ON (s.manager_id = e.employee_id) WHERE s.employee_id IS NULL;")
X(S,"Show for every employee (all of them) how many tasks they have. Employees without tasks must show 0.","SELECT e.last_name, COUNT(t.project_id) FROM employees e LEFT JOIN tasks t ON (e.employee_id = t.employee_id) GROUP BY e.employee_id, e.last_name;","COUNT(*) would count the NULL row as 1.")
X(S,"Show every project name with the last names of the people working on it (if any).","SELECT p.project_name, e.last_name FROM projects p LEFT JOIN tasks t ON (p.project_id = t.project_id) LEFT JOIN employees e ON (t.employee_id = e.employee_id);")
X(S,"Show every department name and its projects, written as a RIGHT JOIN (departments must all appear).","SELECT d.department_name, p.project_name FROM projects p RIGHT JOIN departments d ON (p.department_id = d.department_id);")
X(S,"Show for every employee the number of children (SON or DAUGHTER), 0 for those without.","SELECT e.last_name, COUNT(f.name) FROM employees e LEFT JOIN family_members f ON (e.employee_id = f.employee_id AND f.relationship IN ('SON','DAUGHTER')) GROUP BY e.employee_id, e.last_name;","Put the relationship condition in the ON, otherwise WHERE removes the NULL rows again.")
